const hooks=hookGroups.flatMap(([category,rows],group)=>rows.map(([title,routeText,moment,phrase,followup,opens],index)=>({id:`hook-${group}-${index}`,category,title,routes:routeText.split(','),moment,phrase,followup,opens})));
const hookPositions=new Map();
function hookCard(hook,inline=false){return `<article class="story-card hook-card"><div class="hook-card-heading"><span class="cat-badge">${hook.category}</span><small>${hook.moment}</small></div><h3>${hook.title}</h3><p class="hook-phrase">« ${hook.phrase} »</p><p class="hook-opens"><b>Peut ouvrir :</b> ${hook.opens}</p><details><summary>Si le joueur rebondit</summary><p>« ${hook.followup} »</p><small>Proposer seulement ce que tu peux réellement organiser. S’il ne rebondit pas, reprendre le soin sans insister.</small></details>${inline?'<button class="reference-link" onclick="nextCareHook(this)">Autre accroche</button>':''}</article>`;}
function showStories(){show('stories');renderStories();}
function renderStories(){
 const norm=s=>String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const query=norm(document.getElementById('storySearch').value.trim()),category=document.getElementById('storyCategory').value,route=document.getElementById('hookRoute').value;
 const matches=hooks.filter(h=>(!category||h.category===category)&&(!route||h.routes.includes(route))&&norm([h.title,h.phrase,h.followup,h.opens,h.category,h.moment].join(' ')).includes(query));
 document.getElementById('storyCount').textContent=`${matches.length} / ${hooks.length} accroches`;
 document.getElementById('storyList').innerHTML=matches.length?matches.map(h=>hookCard(h)).join(''):'<p>Aucune accroche trouvée. Essaie un autre mot ou efface un filtre.</p>';
}
function careHookMarkup(){
 const route=activeRouteKind==='surgery'?'checkup':currentFlow;
 const matches=hooks.filter(h=>h.routes.includes(route));
 if(!matches.length)return '';
 const position=hookPositions.get(route)||0;
 return `<details class="care-hook"><summary>Une perche pour une autre scène <small>Facultatif, après la priorité du soin</small></summary><div data-hook-route="${route}">${hookCard(matches[position%matches.length],true)}</div></details>`;
}
function nextCareHook(button){
 const host=button.closest('[data-hook-route]'),route=host.dataset.hookRoute,matches=hooks.filter(h=>h.routes.includes(route));
 const position=(hookPositions.get(route)||0)+1;hookPositions.set(route,position);host.innerHTML=hookCard(matches[position%matches.length],true);
}
document.addEventListener('DOMContentLoaded',()=>{
 const category=document.getElementById('storyCategory');hookGroups.forEach(([name])=>category.append(new Option(name,name)));
 const route=document.getElementById('hookRoute');Object.entries(flows).forEach(([id,flow])=>route.append(new Option(flow.title,id)));
});
